import AppKit
import SwiftUI

/// 剪贴板设置页。
///
/// 改完立刻生效的项（容量、AutoGenerated 开关）不需要重启；
/// 黑名单只影响后续采集，已入库的历史不会被追溯删除 —— 这点在界面上说明，
/// 否则用户会以为加了黑名单就能抹掉以前记下的东西。
struct ClipboardTabView: View {
    @ObservedObject var model: AppModel
    @State private var capacityText = ""
    @State private var newBlocked = ""
    @State private var confirmClear = false
    @State private var notice: String?

    var body: some View {
        VStack(alignment: .leading, spacing: 14) {
            HStack {
                Text("历史容量").frame(width: 130, alignment: .leading)
                TextField("", text: $capacityText).frame(width: 70)
                    .multilineTextAlignment(.trailing)
                    .onSubmit(commitCapacity)
                Text("条（超出后淘汰最旧的非置顶项）")
                    .font(.system(size: 11)).foregroundStyle(.secondary)
            }

            HStack(spacing: 8) {
                Text("列表显示行数").frame(width: 130, alignment: .leading)
                Stepper(value: Binding(
                    get: { model.settings.clipboardVisibleRows },
                    set: { model.setClipboardVisibleRows($0) }),
                        in: ClipboardPanelGeometry.minRows...ClipboardPanelGeometry.maxRows) {
                    Text("\(model.settings.clipboardVisibleRows) 行")
                        .frame(minWidth: 44, alignment: .trailing)
                }
                .fixedSize()
                Button("10") { model.setClipboardVisibleRows(10) }.controlSize(.mini)
                Button("20") { model.setClipboardVisibleRows(20) }.controlSize(.mini)
                Button("30") { model.setClipboardVisibleRows(30) }.controlSize(.mini)
                Spacer()
            }
            Text("面板高度随之变化；超出屏幕可视高度时会自动收进来，不会顶到菜单栏外。")
                .font(.system(size: 11)).foregroundStyle(.secondary)

            Toggle("记录程序自动生成的内容（AutoGenerated 标记）",
                   isOn: Binding(get: { model.settings.recordAutoGenerated },
                                 set: { model.setRecordAutoGenerated($0) }))

            VStack(alignment: .leading, spacing: 6) {
                Text("不记录这些 App").frame(width: 130, alignment: .leading)
                Text("仅影响之后的采集，不会追溯删除已记录的历史。")
                    .font(.system(size: 11)).foregroundStyle(.secondary)
                ForEach(model.settings.blockedApps, id: \.self) { app in
                    HStack(spacing: 8) {
                        Text(app).font(.system(size: 11, design: .monospaced))
                        Button("移除") { model.removeBlockedApp(app) }
                            .controlSize(.mini)
                    }
                }
                HStack(spacing: 8) {
                    TextField("bundle id，如 com.agilebits.onepassword7", text: $newBlocked)
                        .frame(width: 300)
                        .onSubmit(addBlocked)
                    Button("添加", action: addBlocked)
                }
            }

            Divider()
            HStack(spacing: 10) {
                Text("当前已记录 \(model.storedItemCount) 条 · 图片占用 \(model.mediaSizeLabel)")
                    .font(.system(size: 11)).foregroundStyle(.secondary)
                Spacer()
                Button("清空历史…", role: .destructive) { confirmClear = true }
                    .confirmationDialog("确定清空全部剪贴板历史？",
                                        isPresented: $confirmClear, titleVisibility: .visible) {
                        Button("清空", role: .destructive) { model.clearHistory() }
                        Button("取消", role: .cancel) {}
                    } message: {
                        Text("置顶项也会被一并删除，图片文件会一起回收。此操作不可撤销。")
                    }
            }
            if let notice {
                Text(notice).font(.system(size: 11)).foregroundStyle(.secondary)
            }
            Spacer()
        }
        .padding(20)
        .onAppear {
            capacityText = String(model.settings.clipboardCapacity)
            model.refreshClipboardStats()
        }
        .onChange(of: model.settings.clipboardCapacity) { _, newValue in
            if Int(capacityText) != newValue { capacityText = String(newValue) }
        }
    }

    private func addBlocked() {
        let id = newBlocked.trimmingCharacters(in: .whitespaces)
        guard !id.isEmpty else { return }
        model.addBlockedApp(id)
        newBlocked = ""
    }

    private func commitCapacity() {
        guard let n = Int(capacityText.filter(\.isNumber)), n > 0 else {
            notice = "容量必须是正整数，已回退为 \(model.settings.clipboardCapacity)"
            capacityText = String(model.settings.clipboardCapacity)
            return
        }
        // 下限 10：设成 1 会让面板基本没法用，还容易让人以为功能坏了
        let clamped = max(10, min(n, 5_000))
        model.setCapacity(clamped)
        if clamped != n { notice = "已限制到 \(clamped)（允许范围 10–5000）" }
        Task { await model.applyCapacityTrim() }
    }
}
